-- L21-l1-series-games-corrections.rollback.sql (lane otkdata, run O1, audit 06 of 2026-11-08 validated by the owner on 2026-11-09; generated by scripts/anime/a2/corrections/gen.mjs from spec-l21.mjs, do not edit by hand)
--
-- What:   undoes L21: puts back the values and the sources that L15 wrote, for the rows that still hold the corrected value.
-- Needs:  024, L15 (the 100 + 70 character_game_facts rows). After L17 (it owns attrs.affiliation of One Piece, never touched here).
-- WHEN:   apply by the owner after a backup, just after 00:30 UTC of a day on which no scheduled answer is lost (value corrections on a scheduled answer only fix feedback and are fine; production read of 2026-11-09: Jesus Burgess is the One Piece answer of bank day 4, 2026-11-10, so this file aborts until after that day or until the day is swapped), never between 23:50 and 00:30 UTC, and never during a build. The first statements read dle_schedule for today and the next 7 days and abort
--         (nothing is written) if a character that leaves the answers is scheduled there. A guess is stored as the entity id only and its colours are computed on every read, so a game in progress
--         is recoloured at once; the snapshot dle_entities is refreshed in the same transaction.
-- Undo:   L21-l1-series-games-corrections.sql.
-- o1-transaction: single, ONE DO block (atomic on its own, in psql and in the Supabase SQL Editor). Idempotent: a second run changes nothing; a row that already moved to another value is left alone (warning).

do $o1l21r$
begin
perform set_config('lock_timeout', '5s', true);
perform set_config('client_min_messages', 'warning', true);


begin
  if to_regclass('public.character_game_facts') is null or to_regclass('public.entity_sources') is null then
    raise exception 'L21 rollback: 024 and L15 must be applied first';
  end if;
  if (select count(*) from public.character_game_facts where game_id = 'otakudle-one-piece') < 100 or (select count(*) from public.character_game_facts where game_id = 'otakudle-dragon-ball') < 70 then
    raise exception 'L21 rollback: the 100 + 70 facts of L15 are not all there (apply L15 first)';
  end if;
end;

-- Precheck of the next 7 days (AUDITS-COMMON): boa-hancock stops being an answer, so none of them may be today's answer or scheduled in the next 7 days; otherwise the file aborts and is applied after that day.
declare r record;
begin
  if to_regclass('public.dle_schedule') is not null and to_regclass('public.dle_games') is not null then
    for r in
      select g.id as game_id, c.slug, s.bank_day
      from public.dle_games g
      join public.dle_schedule s on s.game_id = g.id
      join public.characters c on c.id::text = s.entity_id
      where g.epoch is not null and (g.id, c.slug) in (('otakudle-one-piece', 'boa-hancock'))
        and s.bank_day in (select public.dle_bank_day(g.epoch, public.dle_utc_date(now()) + k) from generate_series(0, 7) as k)
      union all
      select g.id, c.slug, null from public.dle_games g join public.dle_daily_stats d on d.game_id = g.id and d.play_date >= public.dle_utc_date(now())
      join public.characters c on c.id::text = d.entity_id where (g.id, c.slug) in (('otakudle-one-piece', 'boa-hancock'))
    loop
      raise exception 'L21 rollback: % is the answer of % (bank day %) today or in the next 7 days: apply this file after that day', r.slug, r.game_id, coalesce(r.bank_day::text, 'served today');
    end loop;
  end if;
end;


