  c record; s record; r record; cur jsonb;
  n_changed integer := 0; n_already integer := 0; n_drift integer := 0; n_missing integer := 0;
begin
  for c in select t.id, t.game_id, t.series, t.slug, t.kind, t.col, t.old_v::jsonb as old_v, t.new_v::jsonb as new_v
    from jsonb_to_recordset(fixes) as t(id text, game_id text, series text, slug text, kind text, col text, old_v text, new_v text) order by t.id loop
    select f.character_id, f.attrs, f.hints, f.can_be_target into r
    from public.character_game_facts f
    join public.characters ch on ch.id = f.character_id
    join public.groups g on g.id = ch.group_id and g.site_id = 'anime' and g.slug = c.series
    where ch.slug = c.slug and f.game_id = c.game_id;
    if not found then
      n_missing := n_missing + 1;
      raise warning 'L21 rollback %: no fact row for % / %', c.id, c.game_id, c.slug;
      continue;
    end if;
    cur := case c.kind when 'attr' then r.attrs -> c.col when 'hint' then r.hints -> c.col else to_jsonb(r.can_be_target) end;
    if cur is not distinct from c.old_v then
      if c.kind = 'attr' then
        update public.character_game_facts set attrs = jsonb_set(attrs, array[c.col], c.new_v) where character_id = r.character_id and game_id = c.game_id;
      elsif c.kind = 'hint' then
        update public.character_game_facts set hints = jsonb_set(hints, array[c.col], c.new_v) where character_id = r.character_id and game_id = c.game_id;
      else
        update public.character_game_facts set can_be_target = (c.new_v)::text::boolean where character_id = r.character_id and game_id = c.game_id;
      end if;
      n_changed := n_changed + 1;
    elsif cur is not distinct from c.new_v then
      n_already := n_already + 1;
    else
      n_drift := n_drift + 1;
      raise warning 'L21 rollback %: % / % holds %, neither % nor %: left alone', c.id, c.game_id, c.slug, cur, c.old_v, c.new_v;
      continue;
    end if;
    for s in select w.* from jsonb_to_recordset(srcs) as w(id text, op text, entity_id text, field text, source text, ref text, url text, fetched text) where w.id = c.id loop
      if s.op = 'delete' then
        delete from public.entity_sources where entity_type = 'character' and entity_id = s.entity_id and field = s.field and source = s.source;
      else
        insert into public.entity_sources (entity_type, entity_id, field, source, source_ref, source_url, fetched_at) values ('character', s.entity_id, s.field, s.source, s.ref, s.url, s.fetched::timestamptz)
        on conflict (entity_type, entity_id, field, source) do update set source_ref = excluded.source_ref, source_url = excluded.source_url, fetched_at = excluded.fetched_at
        where (entity_sources.source_ref, entity_sources.source_url, entity_sources.fetched_at) is distinct from (excluded.source_ref, excluded.source_url, excluded.fetched_at);
      end if;
    end loop;
  end loop;
  if n_missing > 0 then
    raise exception 'L21 rollback: % corrections found no row (apply L15 first)', n_missing;
  end if;
  if n_drift = 0 and n_changed not in (0, 45) then
    raise exception 'L21 rollback: % rows changed, expected 0 or 45', n_changed;
  end if;
  raise notice 'L21 rollback: % changed, % already as wanted, % left alone', n_changed, n_already, n_drift;
end;

-- The snapshot the players read (a game that has none is refreshed by its own activation).
begin
  if exists (select 1 from public.dle_entities where game_id = 'otakudle-dragon-ball') then perform public.dle_refresh_entities('otakudle-dragon-ball'); end if;
  if exists (select 1 from public.dle_entities where game_id = 'otakudle-one-piece') then perform public.dle_refresh_entities('otakudle-one-piece'); end if;
end;

-- Nobody scheduled in the next 7 days may have stopped being a possible answer.
declare r record;
begin
  if to_regclass('public.dle_schedule') is not null and to_regclass('public.dle_games') is not null and to_regclass('public.dle_entities') is not null then
    for r in
      select s.game_id, s.entity_id, s.bank_day from public.dle_games g join public.dle_schedule s on s.game_id = g.id
      join public.dle_entities e on e.game_id = s.game_id and e.entity_id = s.entity_id
      where g.id in ('otakudle-dragon-ball', 'otakudle-one-piece') and g.epoch is not null and not (e.can_be_target and e.in_pool)
        and s.bank_day in (select public.dle_bank_day(g.epoch, public.dle_utc_date(now()) + k) from generate_series(0, 7) as k)
    loop
      raise exception 'L21 rollback: entity % of % (bank day %) is scheduled in the next 7 days and is no longer a possible answer', r.entity_id, r.game_id, r.bank_day;
    end loop;
    if to_regclass('public.dle_daily_stats') is not null and exists (select 1 from public.dle_daily_stats d join public.dle_entities e on e.game_id = d.game_id and e.entity_id = d.entity_id
       where d.game_id in ('otakudle-dragon-ball', 'otakudle-one-piece') and d.play_date >= public.dle_utc_date(now()) and not (e.can_be_target and e.in_pool)) then
      raise exception 'L21 rollback: the answer served today is no longer a possible answer';
    end if;
  end if;
end;

notify pgrst, 'reload schema';

end $o1l21r$;
